{
  events: [],
  capture: function(phase, log) {
    var length = log.stack.length();
    var operands = [];
    for (var i = 0; i < length; i++) {
      operands.push(log.stack.peek(i).toString(16));
    }
    this.events.push({
      phase: phase,
      pc: log.getPC(),
      op: log.op.toString(),
      gas: log.getGas(),
      cost: log.getCost(),
      error: log.getError() || null,
      stack: {length: length, peek: operands},
      memory: {length: log.memory.length()}
    });
  },
  step: function(log) { this.capture("step", log); },
  fault: function(log) { this.capture("fault", log); },
  result: function() { return this.events; }
}

